import{_ as c,r as n,o as p,c as d,e as l,a as t,s as a,d as e}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"多站点 - October CMS - 3.x","titleTemplate":false,"description":"了解如何使用多站点翻译内容","frontmatter":{"subtitle":"了解如何使用多站点翻译内容"},"headers":[{"level":2,"title":"管理站点","slug":"管理站点","link":"#管理站点","children":[]},{"level":2,"title":"站点选择器组件","slug":"站点选择器组件","link":"#站点选择器组件","children":[]},{"level":2,"title":"浏览器语言检测","slug":"浏览器语言检测","link":"#浏览器语言检测","children":[]},{"level":2,"title":"站点组","slug":"站点组","link":"#站点组","children":[]},{"level":2,"title":"角色限制","slug":"角色限制","link":"#角色限制","children":[]},{"level":2,"title":"多站点功能","slug":"多站点功能","link":"#多站点功能","children":[{"level":3,"title":"禁用多站点","slug":"禁用多站点","link":"#禁用多站点","children":[]}]},{"level":2,"title":"PHP 接口","slug":"php-接口","link":"#php-接口","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/cms/resources/multisite.md","filePath":"3.x/zh-cn/cms/resources/multisite.md"}'),h={name:"3.x/zh-cn/cms/resources/multisite.md"};function u(g,s,m,v,k,f){const o=n("pre-heading"),r=n("post-heading"),i=n("VideoBlockLink");return p(),d("div",null,[l(o),s[0]||(s[0]=t("h1",null,"多站点",-1)),l(r),l(i,{src:"https://www.youtube.com/watch?v=_kX7P3SEHg8",title:"Multisite Demo",description:"This video demonstrates how to create multilingual sites with October CMS Multisite.",prompt:"Watch the demonstration"}),s[1]||(s[1]=a(`<p>多站点功能允许您从单个 October CMS 安装中管理多个网站，并根据域名分配内容。例如，一个拥有不同国家/地区子站点的电子商务商店。您还可以使用它来管理本地化网站的翻译。</p><h2 id="管理站点"><a href="#管理站点" class="header-anchor">#</a> 管理站点</h2><p>您可以通过访问管理面板的 <strong>设置 → 管理站点</strong> 页面来创建站点。每个安装都包含一个主站点，作为每个请求的默认站点。</p><p>以下配置定义了每个站点：</p><ul><li><strong>启用</strong> - 决定是否可以在前端和管理面板上访问该站点。</li><li><strong>名称</strong> - 指定站点名称。</li><li><strong>唯一代码</strong> - 指定用于通过 API 查找的唯一站点代码。</li><li><strong>主题</strong> - 当此站点处于活动状态时使用的 CMS 主题。</li><li><strong>语言区域</strong> - 用于此站点的应用程序语言区域。</li><li><strong>时区</strong> - 用于此站点的时区。</li><li><strong>自定义应用程序 URL</strong> - 当此站点处于活动状态时使用的 URL，用于邮件模板或链接策略强制使用 URL 等场景。</li><li><strong>使用 CMS 路由前缀</strong> - 定义在每个页面路由之前包含的前缀。在使用共享主机名时，它可以标识此站点。</li><li><strong>定义匹配的主机名</strong> - 使用特定的主机名匹配站点。出于安全原因，您应该为生产站点启用此选项。支持通配符值，例如：<code>*.mydomain.tld</code>。</li><li><strong>为此站点显示颜色</strong> - 启用后，在管理面板顶部显示横幅。用于标识活动站点或区分不同环境，例如，红色表示开发环境，绿色表示预发布环境，无颜色表示生产环境。</li></ul><p>当您创建多个站点时，可以在管理面板中使用站点选择下拉菜单来选择每个站点。</p><h2 id="站点选择器组件"><a href="#站点选择器组件" class="header-anchor">#</a> 站点选择器组件</h2><p><code>sitePicker</code> 组件允许您管理到其他站点的链接。最佳的包含位置是在您的页面或布局模板中。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">sitePicker</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> availableSites <span class="token operator">=</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>查看<a href="./../components/sitepicker.html">站点选择器组件</a>文章，了解如何显示站点 URL 和生成替代页面链接。</p><h2 id="浏览器语言检测"><a href="#浏览器语言检测" class="header-anchor">#</a> 浏览器语言检测</h2><p>当满足以下条件时，October CMS 会配置为根据浏览器的首选语言自动检测匹配的站点。</p><ul><li>组中的所有站点都设置了前缀</li><li>没有其他站点匹配基础 URL</li></ul><p>例如，如果主站点是 <strong>English</strong>，路由前缀为 <code>/en</code>，另一个站点 <strong>French</strong> 的前缀为 <code>/fr</code>，则可以观察到以下行为。</p>`,14)),s[2]||(s[2]=t("div",{class:"table"},[t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"基础 URL"),t("th",null,"行为")])]),t("tbody",null,[t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld/en",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld/en"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,[e("显示 "),t("strong",null,"English"),e(" 站点")])]),t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld/fr",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld/fr"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,[e("显示 "),t("strong",null,"French"),e(" 站点")])]),t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,"根据语言偏好进行重定向")])])])],-1)),s[3]||(s[3]=a(`<p>当用户访问基础 URL 时，系统会自动检测其首选语言并重定向到匹配的站点。匹配的站点基于其语言区域值，如果未找到匹配项，则使用主站点。</p><div class="custom-block tip"><p>您可以使用 <strong>config/cms.php</strong> 文件中的 <code>redirect_policy</code> 值来修改此行为。</p></div><h2 id="站点组"><a href="#站点组" class="header-anchor">#</a> 站点组</h2><p>在初始状态下，多站点有助于使用单一语言创建多个网站，或使用多种语言创建单个网站。站点分组允许您进一步扩展此概念，创建具有多种语言的多个站点。通过导航到 <strong>设置 → 管理站点 → 管理站点组</strong> 创建站点组，创建组后，每个站点都会出现一个组选择字段。</p><p>实际上，每个站点组代表一个网站，属于该组的站点定义代表该站点的替代语言版本。以下示例显示了关于猫和狗的网站的分组站点配置，每个网站有两种语言。</p><div class="table"><table tabindex="0"><thead><tr><th>站点组</th><th>站点名称</th></tr></thead><tbody><tr><td>Dogs</td><td>English</td></tr><tr><td>Dogs</td><td>French</td></tr><tr><td>Cats</td><td>English</td></tr><tr><td>Cats</td><td>French</td></tr></tbody></table></div><p>分组站点仅在其特定组内复制字段。例如，如果 <a href="./../tailor/introduction.html">Tailor 蓝图</a>使用 <code>multisite: sync</code> 选项，记录将仅在同一组中的站点之间同步。</p><h2 id="角色限制"><a href="#角色限制" class="header-anchor">#</a> 角色限制</h2><p>站点定义可以根据管理员角色限制其可见性，这允许您使用专用的管理员角色来管理特定站点。要启用多站点角色限制功能：</p><ol><li>导航到 <strong>管理站点</strong> 并选择一个站点定义</li><li>勾选 <strong>定义管理员角色</strong> 复选框。</li><li>选择允许查看该站点的角色。</li><li>点击 <strong>保存</strong>。</li></ol><p>启用后，该站点将仅在后端面板中对字段中指定的管理员可见。例如，要创建仅供开发人员访问的站点，请在字段中选择 <strong>Developer</strong> 角色。</p><h2 id="多站点功能"><a href="#多站点功能" class="header-anchor">#</a> 多站点功能</h2><p>有一些核心功能默认未启用多站点，例如邮件配置。您可以使用 <strong>config/multisite.php</strong> 文件中 <code>features</code> 部分选择性地启用多站点功能。以下功能键可用于多个站点定义。</p><div class="table"><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td><code>cms_maintenance_setting</code></td><td>维护模式设置对每个站点是独立的</td></tr><tr><td><code>backend_mail_setting</code></td><td>邮件设置对每个站点是独立的</td></tr><tr><td><code>system_asset_combiner</code></td><td>资源合并器缓存键对每个站点是唯一的</td></tr></tbody></table></div><h3 id="禁用多站点"><a href="#禁用多站点" class="header-anchor">#</a> 禁用多站点</h3><p>您可以通过将 <code>enabled</code> 配置设置为 <code>false</code> 值来完全禁用多站点功能。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;enabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span>
</code></pre></div><h2 id="php-接口"><a href="#php-接口" class="header-anchor">#</a> PHP 接口</h2><p><a href="./../../extend/services/site.html">站点服务</a>包含全局 <code>Site</code> 门面，提供用于多站点操作的工具。例如，以下代码在 ID 为 <strong>2</strong> 的站点上下文中查找模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withContext</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Model</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>阅读<a href="./../../extend/services/site.html">站点服务文章</a>了解更多信息。</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4>`,22)),s[4]||(s[4]=t("div",{class:"custom-block also"},[t("ul",null,[t("li",null,[t("a",{href:"https://octobercms.com/features/multisite",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("Multisite Features"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("li",null,[t("a",{href:"./../themes/localization.html"},"Theme Localization")]),t("li",null,[t("a",{href:"./../components/sitepicker.html"},"Site Picker Component")]),t("li",null,[t("a",{href:"./../../extend/database/traits.html"},"Multisite Trait")]),t("li",null,[t("a",{href:"./../../extend/services/site.html"},"Site Service")])])],-1))])}const x=c(h,[["render",u]]);export{b as __pageData,x as default};
